#!/usr/bin/env Rscript
# PILOT TDS L102a - Treatment Disposition and Discontinuation
# Standalone: source-logical original data, doubled simulation, Excel, analysis, RTF.

options(stringsAsFactors=FALSE)
set.seed(20260827)
suppressPackageStartupMessages(library(tidyverse))
script_dir<-function(){a<-commandArgs(FALSE);f<-sub("^--file=","",a[grepl("^--file=",a)]);f<-gsub("~\\+~"," ",f);if(length(f))dirname(normalizePath(f[1]))else getwd()}
OUT_DIR<-script_dir()
xe<-function(x){x[is.na(x)]<-"";x<-gsub("&","&amp;",x,fixed=TRUE);x<-gsub("<","&lt;",x,fixed=TRUE);x<-gsub(">","&gt;",x,fixed=TRUE);gsub('"',"&quot;",x,fixed=TRUE)}
xc<-function(n){z<-character(length(n));for(j in seq_along(n)){k<-n[j];s<-"";while(k>0){k<-k-1;s<-paste0(intToUtf8(65+k%%26),s);k<-k%/%26};z[j]<-s};z}
write_xlsx<-function(d,p){names(d)<-toupper(names(d));td<-tempfile("x");dir.create(td);ds<-c("_rels","docProps","xl","xl/_rels","xl/worksheets");invisible(vapply(file.path(td,ds),dir.create,logical(1),recursive=TRUE));writeLines('<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/><Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/></Types>',file.path(td,"[Content_Types].xml"));writeLines('<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/></Relationships>',file.path(td,"_rels/.rels"));writeLines('<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="SIMULATED_DATA" sheetId="1" r:id="rId1"/></sheets></workbook>',file.path(td,"xl/workbook.xml"));writeLines('<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>',file.path(td,"xl/_rels/workbook.xml.rels"));writeLines('<?xml version="1.0" encoding="UTF-8"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="1"><font><sz val="10"/><name val="Arial"/></font></fonts><fills count="1"><fill><patternFill patternType="none"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="1"><xf xfId="0"/></cellXfs></styleSheet>',file.path(td,"xl/styles.xml"));a<-rbind(names(d),as.matrix(d));rows<-vapply(seq_len(nrow(a)),function(i){cc<-vapply(seq_len(ncol(a)),function(j)sprintf('<c r="%s%d" t="inlineStr"><is><t>%s</t></is></c>',xc(j),i,xe(as.character(a[i,j]))),character(1));sprintf('<row r="%d">%s</row>',i,paste0(cc,collapse=""))},character(1));writeLines(paste0('<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>',paste0(rows,collapse=""),'</sheetData></worksheet>'),file.path(td,"xl/worksheets/sheet1.xml"));writeLines('<?xml version="1.0" encoding="UTF-8"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:creator>PILOT</dc:creator></cp:coreProperties>',file.path(td,"docProps/core.xml"));writeLines('<?xml version="1.0" encoding="UTF-8"?><Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties"><Application>R</Application></Properties>',file.path(td,"docProps/app.xml"));old<-setwd(td);on.exit(setwd(old),add=TRUE);if(file.exists(p))unlink(p);utils::zip(p,list.files(".",recursive=TRUE,all.files=TRUE,no..=TRUE),flags="-q")}
re<-function(x){x<-gsub("\\","\\\\",x,fixed=TRUE);x<-gsub("{","\\{",x,fixed=TRUE);x<-gsub("}","\\}",x,fixed=TRUE);gsub("\n","\\line ",x,fixed=TRUE)}
write_rtf<-function(tab,p,title,foot){con<-file(p,"wb");on.exit(close(con));w<-function(...)writeLines(paste0(...),con,useBytes=TRUE);w("{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 Arial;}}\\landscape\\paperw15840\\paperh12240\\margl600\\margr600\\margt500\\margb600");w("\\pard\\par");w("\\pard\\f0\\fs15 PILOT\\tab Confidential\\tab Page {\\field{\\*\\fldinst PAGE}} of {\\field{\\*\\fldinst NUMPAGES}}\\par");w("\\pard\\qc\\b\\fs20 ",re(title),"\\b0\\par");w("\\pard\\qc\\fs16 Safety Analysis Set\\par\\par");nc<-ncol(tab);ends<-cumsum(c(if(nc==5)5000 else 6800,rep(floor((14100-if(nc==5)5000 else 6800)/(nc-1)),nc-1)));for(i in seq_len(nrow(tab))){bd<-if(i==1)"\\clbrdrt\\brdrs\\brdrw15\\clbrdrb\\brdrs\\brdrw15"else if(i==nrow(tab))"\\clbrdrb\\brdrs\\brdrw15"else"";w("\\trowd\\trgaph70",if(i==1)"\\trhdr"else"",paste0(bd,"\\cellx",ends,collapse=""));for(j in seq_len(nc))w("\\intbl",if(j==1)"\\ql"else"\\qc",if(i==1||i>1&&all(tab[i,-1]==""))"\\b"else"\\b0","\\f0\\fs15 ",re(as.character(tab[i,j])),"\\cell");w("\\row")};w("\\pard\\ql\\fs13\\par ",re(foot),"\\par");w("\\pard\\ql\\fs13 Source: Simulated data generated by this standalone program. Generated: ",format(Sys.Date(),"%d%b%Y"),"\\par}")}
fmt<-function(n,d)if(n==0||d==0)"0"else sprintf("%d (%.1f%%)",n,100*n/d)

STEM<-"02_treatment_disposition_summary"
# Reconstruct the 178-subject source logic: three treatments, mutually exclusive
# end-of-treatment status, and a primary reason only for discontinued subjects.
N_ORIGINAL<-178L
original_data<-tibble(I=seq_len(N_ORIGINAL),RANDFL="Y",SAFFL="Y",USUBJID=sprintf("PILOT-O%04d",seq_len(N_ORIGINAL)),TRT01AN=rep(c(3L,1L,3L,3L,1L,3L,1L,2L,3L,1L,2L),length.out=N_ORIGINAL))
original_data$EOTSTTN<-rep(c(1L,1L,2L,3L,1L,3L,2L,2L,2L,1L,3L,2L),length.out=N_ORIGINAL)
original_data$EOTSTT<-c("Ongoing","Completed","Discontinued")[original_data$EOTSTTN]
reason_labels<-c("Adverse Event","Protocol Deviation","Lost to Follow-up","Withdrawal by Subject","Investigator Discretion","Intolerable Toxicity","Progressive Disease per RECIST","Clinical Progression Without Radiological PD by RE","Other")
disc<-which(original_data$EOTSTTN==3L);original_data$DCTREASN<-NA_integer_;original_data$DCTREASN[disc]<-rep(seq_along(reason_labels),length.out=length(disc));original_data$DCTREAS<-"";original_data$DCTREAS[disc]<-reason_labels[original_data$DCTREASN[disc]]
# Resample complete subject records to exactly twice the source sample.
idx<-c(seq_len(N_ORIGINAL),sample(seq_len(N_ORIGINAL),N_ORIGINAL,replace=TRUE))
simulated_data<-original_data[idx,];simulated_data$I<-seq_len(nrow(simulated_data));simulated_data$USUBJID<-sprintf("PILOT-S%04d",seq_len(nrow(simulated_data)))
stopifnot(nrow(simulated_data)==356,all(names(simulated_data)==toupper(names(simulated_data))),all(simulated_data$DCTREAS[simulated_data$EOTSTTN!=3]==""))
write_xlsx(simulated_data,file.path(OUT_DIR,paste0(STEM,"_simulated_data.xlsx")))
# Original L102a analysis retained: Safety Set, treatment denominators, separate
# disposition/reason counts, dummy rows, percentages, and treatment transpose.
adsl01<-simulated_data%>%filter(SAFFL=="Y")%>%mutate(TREATMENT=TRT01AN)
trttotals<-tibble(TREATMENT=1:3)%>%left_join(adsl01%>%count(TREATMENT,name="TRTTOTAL"),by="TREATMENT")%>%mutate(TRTTOTAL=replace_na(TRTTOTAL,0L))
dummy<-tribble(~SECTION,~ORDER,~LABEL,1,0,"Treatment disposition",1,1,"Ongoing",1,2,"Completed",1,3,"Discontinued",2,0,"Primary reason for discontinuing treatment",2,1,"Adverse Event",2,2,"Protocol Deviation",2,3,"Lost to Follow-up",2,4,"Withdrawal by Subject",2,5,"Investigator Discretion",2,6,"Intolerable Toxicity",2,7,"Progressive Disease per RECIST",2,8,"Clinical Progression Without Radiological PD by RE",2,9,"Other")
actual<-bind_rows(adsl01%>%count(TREATMENT,EOTSTT,name="COUNT")%>%transmute(SECTION=1L,LABEL=EOTSTT,TREATMENT,COUNT),adsl01%>%filter(EOTSTTN==3)%>%count(TREATMENT,DCTREAS,name="COUNT")%>%transmute(SECTION=2L,LABEL=DCTREAS,TREATMENT,COUNT))
counts<-crossing(dummy,tibble(TREATMENT=1:3))%>%left_join(actual,by=c("SECTION","LABEL","TREATMENT"))%>%left_join(trttotals,by="TREATMENT")%>%mutate(COUNT=if_else(ORDER==0,NA_integer_,replace_na(COUNT,0L)),CP=if_else(ORDER==0,"",map2_chr(replace_na(COUNT,0L),TRTTOTAL,fmt)),DISPLAY=if_else(ORDER==0,LABEL,paste0("   ",LABEL)))
wide<-counts%>%select(SECTION,ORDER,DISPLAY,TREATMENT,CP)%>%pivot_wider(names_from=TREATMENT,values_from=CP,names_prefix="TRT")%>%arrange(SECTION,ORDER)
n<-trttotals$TRTTOTAL
tab<-rbind(c("Category",sprintf("Treatment 1\n(N=%d)",n[1]),sprintf("Treatment 2\n(N=%d)",n[2]),sprintf("Treatment 3\n(N=%d)",n[3])),as.matrix(wide%>%select(DISPLAY,TRT1,TRT2,TRT3)))
write_rtf(tab,file.path(OUT_DIR,paste0(STEM,".rtf")),"Table 2. Treatment Disposition and Primary Reason for Discontinuation","Percentages are based on subjects in the Safety Analysis Set within each treatment group. N = number in treatment; n = number in category.")
cat("Created",STEM,"with 356 simulated subjects.\n")
